import { describe, test, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { breakpoints } from 'app/theme/foundation';
import { ZimmCartDrawer } from './zimmCartDrawer.css';

const TABLET_UP = `@media (min-width: ${breakpoints.md})`;
const DESKTOP_UP = `@media (min-width: ${breakpoints.xl})`;

describe('ZimmCartDrawer recipe', () => {
  // Designer requirement: "to prevent the cart changing position depending on errors" — the
  // band must reserve this height even when there is nothing to show. --zimm-scale-1300 = 52px,
  // confirmed in overrides/app/theme/foundation/zimmTokens.ts:168.
  test('messages band reserves the 52px token height even with nothing to show', () => {
    expect(ZimmCartDrawer.baseStyle.messages.minHeight).toBe('var(--zimm-scale-1300)');
  });

  test('messages band gutter widens to the 128px token above the desktop breakpoint', () => {
    // .toEqual against the whole resolved object rather than drilling into a named property on
    // an intermediate const — see the tablet-step test below for why.
    expect(ZimmCartDrawer.baseStyle.messages[DESKTOP_UP]).toEqual({
      paddingInline: 'var(--zimm-scale-6xl)',
    });
  });

  test('mobile default is a single column, full width, with the 32px gutter token', () => {
    expect(ZimmCartDrawer.baseStyle.body.display).toBe('flex');
    expect(ZimmCartDrawer.baseStyle.body.flexDirection).toBe('column');
    expect(ZimmCartDrawer.baseStyle.body.width).toBe('100%');
    expect(ZimmCartDrawer.baseStyle.body.paddingInline).toBe('var(--zimm-scale-2xl)');
  });

  test('tablet step (at/below the desktop breakpoint) stays single-column, fluid width, as an explicit media query — not a computed pixel width', () => {
    // .toEqual against the whole resolved object, not `body[TABLET_UP].display` etc. on an
    // intermediate const: `body` mixes plain mobile-default properties (typed `string`) with two
    // media-query-keyed sub-objects of different shapes, so TypeScript resolves a bracket access
    // keyed by a non-literal-matched `string` (TABLET_UP's own type) to the union of all three
    // property-value shapes, not the one that's actually there at runtime — confirmed directly
    // via `npx tsc --noEmit` (a `.property` access on that union then fails to compile even
    // though the runtime value underneath is exactly what's asserted here). `.toEqual(...)`
    // takes the whole (union-typed) value without narrowing, so it isn't affected — matching
    // zimmDrawer.css.test.ts's own `.toEqual(...)` usage for the same multi-property, media-query
    // shape.
    expect(ZimmCartDrawer.baseStyle.body[TABLET_UP]).toEqual({
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      paddingInline: 'var(--zimm-scale-2xl)', // 32px — the tablet step's gutter
    });
  });

  test('desktop step (above the desktop breakpoint) switches to the two-column items/totals grid, as an explicit media query', () => {
    expect(ZimmCartDrawer.baseStyle.body[DESKTOP_UP]).toEqual({
      display: 'grid',
      gridTemplateColumns: '22.5rem 26.875rem', // 360px / 430px
      columnGap: 'var(--zimm-scale-3500)', // 140px
      paddingInline: 'var(--zimm-scale-6xl)', // 128px
    });
  });

  test('footer slot gutter matches messages/body at each step', () => {
    expect(ZimmCartDrawer.baseStyle.footer.paddingInline).toBe('var(--zimm-scale-2xl)');
    expect(ZimmCartDrawer.baseStyle.footer[DESKTOP_UP]).toEqual({
      paddingInline: 'var(--zimm-scale-6xl)',
    });
  });

  // Regression guard for the exact mistake this build step's own instructions warned against:
  // a fluid tablet width must never collapse into a single computed/hardcoded pixel number
  // (e.g. "659.2px") — reading the raw source file, not just the resolved object, so this would
  // still catch a stray literal even if it were never referenced by the assertions above.
  test('no computed/hardcoded fluid-width pixel value anywhere in the recipe file', () => {
    const source = readFileSync(path.resolve(__dirname, './zimmCartDrawer.css.ts'), 'utf8');
    expect(source).not.toContain('659.2');
    expect(source).not.toMatch(/\d+\.\d+px/);
  });
});

